functions.normal_rand:
double normal_rand(double mean, double stddev)
{
    double u, r, theta;
    double x;
    double norm_rv;
    u = 0.0;
    while (u == 0.0)
        u = rand_val();
    r = sqrt(-2.0 * log(u));
    theta = 0.0;
    while (theta == 0.0)
        theta = 2.0 * 3.14159265 * rand_val();
    x = r * cos(theta);
    norm_rv = (x * stddev) + mean;
    return norm_rv;
}

functions.gcd:
uint64_t gcd(uint64_t x, uint64_t y)
{
    while (x != y)
    {
        if (x > y)
            x -= y;
        else
            y -= x;
    }
    return x;
}

functions.xgcd:
Xgcd xgcd(uint64_t x, uint64_t y)
{
    int64_t prev_a = 1;
    int64_t a = 0;
    int64_t prev_b = 0;
    int64_t b = 1;
    while (y != 0)
    {
        int64_t q = (int64_t)(x / y);
        int64_t temp = (int64_t)(x % y);
        x = y;
        y = (uint64_t)temp;
        temp = a;
        a = prev_a - (q * a);
        prev_a = temp;
        temp = b;
        b = prev_b - (q * b);
        prev_b = temp;
    }
    Xgcd result = {.gcd = x, .a = prev_a, .b = prev_b};
    return result;
}

functions.are_coprime:
int are_coprime(uint64_t x, uint64_t y)
{
    return !(gcd(x, y) > 1);
}

functions.randrange:
uint64_t randrange(uint64_t lower, uint64_t upper)
{
    return (rand() % (upper - lower + 1)) + lower;
}

functions.randinverse:
Pair randinverse(uint64_t value)
{
    uint64_t a = randrange(2, value - 1);
    while (!are_coprime(a, value))
        a = randrange(2, value - 1);
    Xgcd result = xgcd(a, value);
    Pair p = {.first = a, .second = result.a > 0 ? (uint64_t)result.a : (uint64_t)(result.a + (int64_t)value)};
    return p;
}

